begin;
select no_plan();
create function pg_temp.bundle() returns jsonb language sql as $$select $fixture${"schema":"gina.library-import.v1","package_key":"test-library-intake","revision":1,"previous_hash":null,"title":"Test import package","grade":5,"subject":"Matematik","provenance":{"locale":"tr","curriculum_reference":{"programme_url":"https://tymm.meb.gov.tr/ortaokul-matematik-dersi/unite/448?kod=MAB3","programme_page_updated":"2026-09-04","checked_on":"2026-11-03","distribution_index":"https://odsgm.meb.gov.tr/www/1donem-konu-soru-dagilim-tablolari-2026-2027/icerik/1724","candidate_scenario_id":"tr-2026-2027-t1-ilkmat2-g5-d6","candidate_source_sha256":"d5429b5962a08adc04acd71ceaae2d517bca507f8b4cf94354bcd55a9670aebf","mapping_status":"proposed_pending_subject_review"},"programme_version":"2026-09-04 web programme; implementation/school applicability pending review","school_track_applicability":"pending_review","assessment_notes":["20 items form a pool, not a 20-question compulsory session or an official school exam.","Questions sharing a source are related observations; do not count them as independent evidence of mastery.","All difficulty labels are estimates; no empirical calibration or official approval.","Schematic drawing/description does not certify compass, ruler or protractor manipulation.","Do not grade drawing neatness, motor control, gender, handwriting style or response speed."],"private_note":"PRIVATE_PROVENANCE_SECRET"},"assets":[{"key":"segments","mime":"image/png","sha256":"890c8dc04fe5952ec0d0af6efac019b10bb3287d116b22adcca2e1bd5effdeb8","width":1,"height":1,"base64":"iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAIAAACQd1PeAAAADElEQVR4nGNwcHAAAAGEAMGDX2mUAAAAAElFTkSuQmCC"}],"sources":[{"key":"segments","title":"İki çizim","body":"A ve B arasında iki ucu noktayla gösterilmiş bir çizim; C noktasından başlayıp D üzerinden sağa doğru devam eden, ucunda ok bulunan başka bir çizim var.","alt":"AB çiziminde iki uç nokta var. CD çiziminde başlangıç C; D üzerinden sağa uzanan ok var.","asset_key":"segments","minimum_reading_width":0,"provenance":{"origin":"original_gina_mathematical_diagram","svg_sha256":"a7465f14b876c2ac11a84384c0082f5d16d5fee29cd75b927b8b3c2a1882709b","color_space":"sRGB"}}],"questions":[{"key":"gina-g5-math-geometry-01","revision":1,"source_key":"segments","student":{"grade":5,"subject":"Matematik","topic":"Geometrik şekiller","kind":"open_ended","difficulty":"kolay","stem":"AB ve CD çizimlerinin geometrik adlarını yaz. Uç noktaları ve devam yönleri bakımından aralarındaki farkı açıkla.","choices":[]},"teacher":{"correct_key":null,"expected_answer":"TEACHER_ANSWER_SECRET","solution":"İki uçta nokta bulunan AB sınırlıdır. CD’de başlangıç C ve devamı gösteren bir ok vardır.","explanation":"Nokta ile ok işaretlerini karşılaştır; bir çizimin devam edip etmediğine onlar karar verir.","rubric":{"max_points":4,"scoring":"Her ölçüt ayrı değerlendirilir. Listelenen alt koşullar tamamlanınca o ölçütün puanı verilir; diğer ölçütler bundan bağımsızdır. Eşdeğer gerekçe ve gösterimler kabul edilir.","criteria":[{"id":"c1","points":1,"criterion":"AB’yi doğru parçası olarak adlandırır."},{"id":"c2","points":1,"criterion":"CD’yi ışın olarak adlandırır."},{"id":"c3","points":1,"criterion":"AB’nin iki uç noktayla sınırlı olduğunu belirtir."},{"id":"c4","points":1,"criterion":"CD’nin C’den başlayıp D yönünde devam ettiğini belirtir."}],"missing_answer":"not_answered; eksik öğrenme veya sıfır yeterlilik sonucu çıkarma","review_required":true},"common_misconception":"Ok ucunu ikinci uç nokta sanmak.","next_step":"Nokta ile ok işaretlerini karşılaştır; bir çizimin devam edip etmediğine onlar karar verir."},"metadata":{"curriculum":{"candidate_code":"MAT.5.3.2","mapping_status":"proposed_pending_subject_review","evidence_scope":"reasoning"},"response":{"mode":"text_or_drawing","precise_screen_measurement_required":false,"required_tools":[],"accommodation":"Metin veya anlamı açık etiketli çizim kabul edilir; yazı güzelliği puanlanmaz."},"evidence_unit":"segments","depends_on_question_ids":[],"provenance":{"authoring":"Codex-authored original draft, not copied from an exam","created_on":"2026-11-03","paid_provider_call":false},"difficulty_calibration":"editorial_estimate_not_empirical","private_note":"PRIVATE_METADATA_SECRET"}},{"key":"gina-g5-math-geometry-02","revision":1,"source_key":"segments","student":{"grade":5,"subject":"Matematik","topic":"Geometrik şekiller","kind":"open_ended","difficulty":"orta","stem":"Defterinde E ve F adlı iki farklı nokta göster. E’den başlayıp F yönünde devam eden bir ışını şematik çiz veya nasıl çizileceğini tarif et. Düz çizgiyi oluşturmak için hangi aracı seçerdin? Neden?","choices":[]},"teacher":{"correct_key":null,"expected_answer":"E başlangıçtır; çizgi F’den geçer ve F yönünde bir okla devam eder. Düz çizgi için cetvel/çizgeç veya dijital ışın aracı seçilir.","solution":"E ve F işaretlenir. Cetvel iki noktaya hizalanır. E’den başlayıp F’den geçen çizgi F yönüne uzatılır; devam yönü okla gösterilir.","explanation":"Işının başlangıcını ve devam yönünü ayrı işaretle. Ekranda kusursuz düz çizmek gerekmiyor.","rubric":{"max_points":4,"scoring":"Her ölçüt ayrı değerlendirilir. Listelenen alt koşullar tamamlanınca o ölçütün puanı verilir; diğer ölçütler bundan bağımsızdır. Eşdeğer gerekçe ve gösterimler kabul edilir.","criteria":[{"id":"c1","points":1,"criterion":"E başlangıç noktasını doğru belirler."},{"id":"c2","points":1,"criterion":"Çizgi veya tarif F’den geçer."},{"id":"c3","points":1,"criterion":"Devam yönünü F yönündeki okla veya eşdeğer sözle gösterir."},{"id":"c4","points":1,"criterion":"Cetvel/çizgeç/dijital ışın aracını düz çizgi oluşturma gerekçesiyle seçer."}],"missing_answer":"not_answered; eksik öğrenme veya sıfır yeterlilik sonucu çıkarma","review_required":true},"common_misconception":"E’nin gerisine de ok ekleyerek ışını doğruya çevirmek.","next_step":"Işının başlangıcını ve devam yönünü ayrı işaretle. Ekranda kusursuz düz çizmek gerekmiyor."},"metadata":{"curriculum":{"candidate_code":"MAT.5.3.1","mapping_status":"proposed_pending_subject_review","evidence_scope":"tool_selection_and_schematic_representation_not_instrument_performance"},"response":{"mode":"drawing_or_description","precise_screen_measurement_required":false,"required_tools":[],"accommodation":"Kalem zorunlu değildir. Çizim istenen soruda şeklin uçlarını, ok yönünü ve bağlantılarını yazıyla açıkça tarif etmek de kabul edilir. Bu alternatif gerçek araç kullanma becerisi kanıtı sayılmaz."},"evidence_unit":"question-02","depends_on_question_ids":[],"provenance":{"authoring":"Codex-authored original draft, not copied from an exam","created_on":"2026-11-03","paid_provider_call":false},"difficulty_calibration":"editorial_estimate_not_empirical"}}]}$fixture$::jsonb$$;

insert into auth.users(id,email) values('00000000-0000-4000-8000-000000004201','publish-admin@test.local'),('00000000-0000-4000-8000-000000004202','publish-parent@test.local'),('00000000-0000-4000-8000-000000004203','publish-admin2@test.local');
insert into public.admins(user_id) values('00000000-0000-4000-8000-000000004201'),('00000000-0000-4000-8000-000000004203');
insert into public.families(id,name,created_by) values('10000000-0000-4000-8000-000000004202','Publication test','00000000-0000-4000-8000-000000004202');
insert into public.family_members(family_id,user_id) values('10000000-0000-4000-8000-000000004202','00000000-0000-4000-8000-000000004202');
create temp table package(id uuid);grant all on package to authenticated;
create temp table pub_state(fp text,result jsonb);grant all on pub_state to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000004201","role":"authenticated","gina":{"admin":true}}',true);
insert into package select (public.admin_import_library_bundle(gen_random_uuid(),pg_temp.bundle()||'{"package_key":"test-publication"}')->>'id')::uuid;
insert into pub_state(fp) select public.admin_library_publication((select id from package))#>>'{checks,review_fingerprint}';
select is(public.admin_library_publication((select id from package))#>>'{checks,suitable_count}','0','unreviewed package visible as not ready');
select is(public.admin_library_publication((select id from package))#>>'{checks,missing_media}','1','uncertified source blocks publication');
create function pg_temp.publish(req uuid, ver int, fp text, status text default 'published', reason text default '') returns jsonb language sql as $$
 select public.admin_set_library_publication(req,(select id from package),ver,fp,'Geometri çalışmaları','Kaynaklı iki soru',array['plus','pro']::public.plan_code[],'Test programı 2026',true,status,reason);
$$;
select throws_ok($$select pg_temp.publish(gen_random_uuid(),0,(select fp from pub_state))$$,'P0001','library_publication_review_required','unreviewed package cannot publish');
select public.admin_review_library_question(gen_random_uuid(),(select id from package),'gina-g5-math-geometry-01',1,0,'suitable','Checked');
select public.admin_review_library_question(gen_random_uuid(),(select id from package),'gina-g5-math-geometry-02',1,0,'suitable','Checked');
select throws_ok($$select pg_temp.publish(gen_random_uuid(),0,(select fp from pub_state))$$,'P0001','library_publication_review_changed','old review fingerprint rejected');
update pub_state set fp=public.admin_library_publication((select id from package))#>>'{checks,review_fingerprint}';
select throws_ok($$select pg_temp.publish(gen_random_uuid(),0,(select fp from pub_state))$$,'P0001','library_publication_media_required','review approval cannot bypass media preparation');
select throws_ok($$select public.prepare_library_delivery_media('00000000-0000-4000-8000-000000004201',(select id from package),'[]')$$,'42501',null,'browser cannot attest media');
reset role;set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select throws_ok($$select public.admin_library_publication(gen_random_uuid())$$,'42501',null,'service has no publication reader grant');
select throws_ok($$select public.prepare_library_delivery_media('00000000-0000-4000-8000-000000004202',gen_random_uuid(),'[]')$$,'42501','forbidden','non-admin media actor rejected');
reset role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select lives_ok($$select public.prepare_library_delivery_media('00000000-0000-4000-8000-000000004201',(select id from package),jsonb_build_array(jsonb_build_object('source_hash',pg_temp.bundle()#>>'{assets,0,sha256}','base64',pg_temp.bundle()#>>'{assets,0,base64}')))$$,'trusted media result retained');
select lives_ok($$select public.prepare_library_delivery_media('00000000-0000-4000-8000-000000004201',(select id from package),jsonb_build_array(jsonb_build_object('source_hash',pg_temp.bundle()#>>'{assets,0,sha256}','base64',pg_temp.bundle()#>>'{assets,0,base64}')))$$,'media retry safe');
select is((select count(*)::int from gina.library_delivery_assets where source_hash=pg_temp.bundle()#>>'{assets,0,sha256}'),1,'one canonical asset');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000004201","role":"authenticated","gina":{"admin":true}}',true);
select throws_ok($$select public.admin_set_library_publication(gen_random_uuid(),(select id from package),0,(select fp from pub_state),'Geometri çalışmaları','',array['plus']::public.plan_code[],'Test programı',false,'published')$$,'P0001','library_publication_input','explicit confirmation required');
select throws_ok($$select public.admin_set_library_publication(gen_random_uuid(),(select id from package),0,(select fp from pub_state),'Geometri çalışmaları','',array['plus','plus']::public.plan_code[],'Test programı',true,'published')$$,'P0001','library_publication_input','duplicate plans rejected');
update pub_state set result=pg_temp.publish('20000000-0000-4000-8000-000000004201',0,fp);
select is((select result->>'version' from pub_state),'1','first publication revision');
select is(pg_temp.publish('20000000-0000-4000-8000-000000004201',0,(select fp from pub_state)),(select result from pub_state),'same request replays exact receipt');
select throws_ok($$select pg_temp.publish('20000000-0000-4000-8000-000000004201',1,(select fp from pub_state))$$,'P0001','library_publication_request_conflict','request meaning immutable');
select throws_ok($$select pg_temp.publish(gen_random_uuid(),0,(select fp from pub_state))$$,'P0001','library_publication_changed','stale publication does not overwrite');
select is(public.admin_get_library_import((select id from package),false)->>'status','draft','original package remains immutable draft');
select is(public.admin_library_publication((select id from package))#>>'{publication,status}','published','separate release stored');
select throws_ok($$select * from gina.library_publications$$,'42501',null,'no direct publication read');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000004203","role":"authenticated","gina":{"admin":true}}',true);
select throws_ok($$select pg_temp.publish('20000000-0000-4000-8000-000000004201',0,(select fp from pub_state))$$,'P0001','library_publication_request_conflict','receipt scoped to original actor');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000004202","role":"authenticated","gina":{"role":"parent","family_id":"10000000-0000-4000-8000-000000004202"}}',true);
select throws_ok($$select public.admin_library_publication((select id from package))$$,'42501','forbidden','parent cannot read publication control');
select throws_ok($$select pg_temp.publish(gen_random_uuid(),1,(select fp from pub_state))$$,'42501','forbidden','parent cannot publish');
select is(public.get_published_library_packages(5,'Matematik'),'[]'::jsonb,'release gate defaults closed');
reset role;update public.app_settings set value='true' where key='library_packages.enabled';
set local role authenticated;
select is(jsonb_array_length(public.get_published_library_packages(5,'Matematik')),1,'catalogue returns published scope after rollout gate');
select is(public.get_published_library_packages(5,'Matematik')#>>'{0,accessible}','false','free plan cannot access plus-pro release');
select ok(public.get_published_library_packages(5,'Matematik')::text not like '%SECRET%' and not(public.get_published_library_packages(5,'Matematik')->0 ? 'review_fingerprint'),'catalogue has no answers private metadata or review details');
select is(public.get_published_library_packages(6,'Matematik'),'[]'::jsonb,'other grade excluded');
select is(public.get_published_library_packages(5,'Fen'),'[]'::jsonb,'other subject excluded');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000004201","role":"authenticated","gina":{"admin":true}}',true);
select public.admin_review_library_question(gen_random_uuid(),(select id from package),'gina-g5-math-geometry-01',1,1,'changes_requested','Fix source');
select is(public.admin_library_publication((select id from package))->>'review_current','false','review edit suspends current release');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000004202","role":"authenticated","gina":{"role":"parent","family_id":"10000000-0000-4000-8000-000000004202"}}',true);
select is(public.get_published_library_packages(5,'Matematik'),'[]'::jsonb,'changed review removed from catalogue immediately');
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000004201","role":"authenticated","gina":{"admin":true}}',true);
select throws_ok($$select pg_temp.publish(gen_random_uuid(),1,(select fp from pub_state),'archived','')$$,'P0001','library_publication_input','archive reason required');
select is(pg_temp.publish(gen_random_uuid(),1,(select fp from pub_state),'archived','Review changed')->>'status','archived','archive allowed despite changed review');
reset role;
select is((select count(*)::int from gina.library_publication_requests),2,'retry creates no extra publication decision');
select is((select count(*)::int from public.audit_log where actor_id='00000000-0000-4000-8000-000000004201' and action like 'library_package.%'),2,'one audit per decision');
select is((select count(*)::int from public.library_redemptions where family_id='10000000-0000-4000-8000-000000004202'),0,'publication spends no family quota');
delete from public.admins where user_id='00000000-0000-4000-8000-000000004201';
set local role authenticated;
select throws_ok($$select pg_temp.publish('20000000-0000-4000-8000-000000004201',0,(select fp from pub_state))$$,'42501','forbidden','revoked admin cannot replay');
reset role;
select lives_ok($$delete from auth.users where id='00000000-0000-4000-8000-000000004201'$$,'publication does not block account deletion');
select * from finish();rollback;
